// ============================================================
// 1. FETCH AI AGENT DATA SAFELY
// ============================================================

const aiAgentData = $('AI Agent').first().json || {};

const items =
  Array.isArray(aiAgentData.output)
    ? aiAgentData.output
    : [];

const intermediateSteps =
  Array.isArray(aiAgentData.intermediateSteps)
    ? aiAgentData.intermediateSteps
    : [];


// ============================================================
// 2. EXTRACT RAW ARTICLE RESULTS
//
// Supports:
//   A. News Scrapper
//   B. NewsAPI_-_Get_Article_by_URI
// ============================================================

const rawArticleMap = {};

for (const step of intermediateSteps) {

  const toolName =
    String(step?.action?.tool || "")
      .trim()
      .toLowerCase();

  let obs = step?.observation;

  if (!obs) {
    continue;
  }


  // ----------------------------------------------------------
  // Observation may be returned as a JSON string
  // ----------------------------------------------------------

  if (typeof obs === "string") {

    try {
      obs = JSON.parse(obs);
    } catch (error) {
      continue;
    }
  }


  // ----------------------------------------------------------
  // Normalize array wrapper
  // ----------------------------------------------------------

  const payloads =
    Array.isArray(obs)
      ? obs
      : [obs];


  for (const payload of payloads) {

    if (
      !payload ||
      typeof payload !== "object"
    ) {
      continue;
    }


    // ========================================================
    // A. NEWS SCRAPPER
    //
    // Expected:
    //
    // {
    //   "articles": {
    //     "results": [
    //       {
    //         "uri": "...",
    //         "title": "...",
    //         "body": "..."
    //       }
    //     ]
    //   }
    // }
    // ========================================================

    if (
      toolName === "news_scrapper" &&
      payload.articles &&
      Array.isArray(payload.articles.results)
    ) {

      for (const article of payload.articles.results) {

        if (
          !article ||
          typeof article !== "object"
        ) {
          continue;
        }


        const id =
          article.uri ||
          article.articleId ||
          article.id;


        if (!id) {
          continue;
        }


        rawArticleMap[String(id)] = article;
      }

      continue;
    }


    // ========================================================
    // B. NEWSAPI - GET ARTICLE BY URI
    //
    // Actual NewsAPI.ai response:
    //
    // [
    //   {
    //     "9428707710": {
    //       "info": {
    //         "uri": "9428707710",
    //         "title": "...",
    //         "body": "..."
    //       }
    //     }
    //   }
    // ]
    //
    // We extract:
    //
    // payload
    //   ↓
    // payload["9428707710"]
    //   ↓
    // .info
    //   ↓
    // article
    // ========================================================

    if (
      toolName === "newsapi_-_get_article_by_uri"
    ) {

      for (
        const [uri, value]
        of Object.entries(payload)
      ) {

        if (
          !value ||
          typeof value !== "object"
        ) {
          continue;
        }


        const article =
          value.info;


        if (
          !article ||
          typeof article !== "object"
        ) {
          continue;
        }


        const id =
          article.uri ||
          uri;


        if (!id) {
          continue;
        }


        rawArticleMap[String(id)] =
          article;
      }

      continue;
    }
  }
}


// ============================================================
// 3. OUTPUT ARRAYS
// ============================================================

const outputItems = [];

const quarantineItems = [];


// ============================================================
// 4. PROCESS AI CLASSIFICATIONS
// ============================================================

items.forEach(c => {

  if (
    !c ||
    !c.articleId
  ) {
    return;
  }


  const articleId =
    String(c.articleId);


  // ==========================================================
  // 5. FIND MATCHING RAW ARTICLE
  // ==========================================================

  const raw =
    rawArticleMap[articleId];


  // ==========================================================
  // 6. EMPTY-SHELL DETECTION
  //
  // If AI Agent returned an articleId but the matching
  // article was not found in either:
  //
  //   - News Scrapper
  //   - Get Article by URI
  //
  // quarantine it.
  // ==========================================================

  if (
    !raw ||
    typeof raw !== "object" ||
    Object.keys(raw).length === 0
  ) {

    quarantineItems.push({

      articleId:
        articleId,

      dataType:
        c.dataType || "news",

      relevant:
        c.relevant ?? false,

      relevance_confidence:
        c.relevance_confidence ?? 0,

      relevance_reason:
        c.relevance_reason || "",

      articleDataStatus:
        "quarantined_missing_scraper_data",

      quarantineReason:
        "AI classification exists but matching raw article was not found in News Scrapper or NewsAPI Get Article by URI."

    });

    return;
  }


  // ==========================================================
  // 7. SOURCE INFORMATION
  // ==========================================================

  const source =
    raw.source || {};

  const sourceLocation =
    source.location || {};


  // ==========================================================
  // 8. PUBLISHER LOCATION
  //
  // ONLY the location returned by the API.
  //
  // Example:
  //   San Francisco
  //   Kuala Lumpur
  //   London
  //
  // Do NOT convert this into country.
  // ==========================================================

  const publisherLocation =
    sourceLocation?.label?.eng || "";


  // ==========================================================
  // 9. PUBLISHER COUNTRY
  //
  // ONLY take country from:
  //
  // source.location.country.label.eng
  //
  // NEVER:
  //
  // publisherCountry = publisherLocation
  // ==========================================================

  const publisherCountry =
    sourceLocation?.country?.label?.eng || "";


  // ==========================================================
  // 10. PUBLISHER LOCATION VALIDATED
  //
  // Preserve the API value exactly.
  // ==========================================================

  const publisherLocationValidated =
    source?.locationValidated ?? false;


  // ==========================================================
  // 11. PUBLISHER TYPE / CATEGORY
  //
  // Capture only values actually returned by API.
  // ==========================================================

  const publisherType =
    source?.type ||
    source?.sourceType ||
    source?.mediaType ||
    source?.category ||
    "";


  const publisherGroup =
    source?.group ||
    source?.groupUri ||
    "";


  // ==========================================================
  // 12. STANDARDIZED ARTICLE OBJECT
  // ==========================================================

  const article = {

    articleId:
      articleId,


    articleTitle:
      raw.title || "",


    url:
      raw.url || "",


    language:
      raw.lang || "",


    author:
      (
        raw.authors &&
        raw.authors[0] &&
        raw.authors[0].name
      ) || "",


    dataType:
      raw.dataType || "news",


    publishedDate:
      raw.dateTimePub ||
      raw.dateTime ||
      raw.date ||
      "",


    publisherName:
      source.title || "",


    publisherDomain:
      source.uri || "",


    // --------------------------------------------------------
    // Publisher Location
    // --------------------------------------------------------

    publisherLocation:
      publisherLocation,


    // --------------------------------------------------------
    // Publisher Country
    // --------------------------------------------------------

    publisherCountry:
      publisherCountry,


    // --------------------------------------------------------
    // API validation status
    // --------------------------------------------------------

    publisherLocationValidated:
      publisherLocationValidated,


    // --------------------------------------------------------
    // Publisher type/category
    // --------------------------------------------------------

    publisherType:
      publisherType,


    publisherGroup:
      publisherGroup,


    // --------------------------------------------------------
    // Other article metadata
    // --------------------------------------------------------

    concepts:
      raw.concepts || [],


    categories:
      raw.categories || [],


    articleLocation:
      raw.location
        ? String(raw.location)
        : "null",


    duplicateList:
      raw.duplicateList || [],


    duplicateFlag:
      String(
        raw.isDuplicate ?? false
      ),


    originalArticleReference:
      raw.originalArticle
        ? String(raw.originalArticle)
        : "null",


    // --------------------------------------------------------
    // Preserve complete raw NewsAPI response
    // --------------------------------------------------------

    rawNewsApiResponse:
      raw,


    // --------------------------------------------------------
    // Article body
    // --------------------------------------------------------

    body:
      raw.body || "",


    // --------------------------------------------------------
    // AI relevance classification
    // --------------------------------------------------------

    relevant:
      c.relevant !== undefined
        ? c.relevant
        : false,


    relevance_confidence:
      c.relevance_confidence !== undefined
        ? c.relevance_confidence
        : 0,


    relevance_reason:
      c.relevance_reason || "",


    // --------------------------------------------------------
    // Article data status
    // --------------------------------------------------------

    articleDataStatus:
      "complete"
  };


  // ==========================================================
  // 13. CREATE FRONTMATTER
  // ==========================================================

  const frontmatterFields = {
    ...article
  };


  // Body is added separately
  delete frontmatterFields.body;


  // Raw response is added separately
  delete frontmatterFields.rawNewsApiResponse;


  let frontmatter =
    "---\n";


  for (
    const [key, value]
    of Object.entries(frontmatterFields)
  ) {

    let safeValue;


    if (
      value !== null &&
      typeof value === "object"
    ) {

      safeValue =
        JSON.stringify(value)
          .replace(
            /'/g,
            "''"
          );

    } else {

      safeValue =
        String(value ?? "")
          .replace(
            /'/g,
            "''"
          );
    }


    frontmatter +=
      `${key}: '${safeValue}'\n`;
  }


  // ==========================================================
  // 14. ADD RAW NEWSAPI.AI RESPONSE
  // ==========================================================

  const safeRawResponse =
    JSON.stringify(
      article.rawNewsApiResponse || {}
    )
      .replace(
        /'/g,
        "''"
      );


  frontmatter +=
    `rawNewsApiResponse: '${safeRawResponse}'\n`;


  frontmatter +=
    "---\n\n";


  // ==========================================================
  // 15. FINAL MARKDOWN CONTENT
  // ==========================================================

  const finalMarkdownFile =
    frontmatter +
    article.body;


  // ==========================================================
  // 16. SAFE FILE NAME
  // ==========================================================

  const cleanId =
    String(article.articleId)
      .replace(
        /[^a-zA-Z0-9]/g,
        "_"
      );


  const cleanSlug =
    (
      article.articleTitle ||
      "untitled"
    )
      .toLowerCase()
      .replace(
        /[^a-z0-9]/g,
        "-"
      )
      .replace(
        /-+/g,
        "-"
      )
      .replace(
        /^-|-$/g,
        ""
      )
      .slice(
        0,
        50
      )
      .replace(
        /-$/,
        ""
      );


  const fileName =
    `${cleanId}-${cleanSlug}.md`
      .trim();


  // ==========================================================
  // 17. PUSH FINAL ARTICLE
  // ==========================================================

  outputItems.push({

    json: {
      fileName,
      ...article
    },


    binary: {

      data: {

        data:
          Buffer
            .from(
              finalMarkdownFile,
              "utf-8"
            )
            .toString("base64"),


        mimeType:
          "text/markdown",


        fileName:
          fileName
      }
    }
  });

});


// ============================================================
// 18. RETURN NORMAL ARTICLES
//
// Empty-shell articles are NOT returned to normal pipeline.
// ============================================================

return outputItems;
